
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_pbe_gaussian_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_pbe_gaussian", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.416891531180192e-02, -6.312571033415372e-02, -6.163005392225070e-02, -5.948884636987757e-02, -5.643051640705960e-02, -5.208016051422199e-02, -4.594586931269373e-02, -3.748842736832004e-02, -2.658438669813499e-02, -1.528039551026104e-02, -1.095369089851946e-02, -3.779763095330896e-02, -4.590632786254358e-02, -3.174801594224301e-02, -1.579057062433999e-02, -3.671322919865360e-03, -2.020454756751086e-04, -1.843030263214807e-06, -1.891736047729215e-09, -7.486710886497292e-14]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


